Here's a complete Flappy Bird in a single HTML file. Save it as `flappy.html` and open it in a browser.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Flappy Bird</title>
<style>
  body { margin: 0; background: #222; display: flex; justify-content: center; align-items: center; height: 100vh; }
  canvas { background: #70c5ce; border: 2px solid #000; }
</style>
</head>
<body>
<canvas id="c" width="360" height="560"></canvas>
<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");

const GRAVITY = 0.45;
const FLAP = -7.5;
const PIPE_W = 60;
const GAP = 150;
const PIPE_SPEED = 2.5;
const PIPE_INTERVAL = 90; // frames
const GROUND_H = 60;

let bird, pipes, score, best = 0, frame, state; // state: "ready" | "playing" | "over"

function reset() {
  bird = { x: 90, y: canvas.height / 2, r: 14, vy: 0 };
  pipes = [];
  score = 0;
  frame = 0;
  state = "ready";
}

function flap() {
  if (state === "ready") state = "playing";
  if (state === "playing") bird.vy = FLAP;
  else if (state === "over") reset();
}

window.addEventListener("keydown", e => {
  if (e.code === "Space") { e.preventDefault(); flap(); }
});
canvas.addEventListener("mousedown", flap);
canvas.addEventListener("touchstart", e => { e.preventDefault(); flap(); });

function spawnPipe() {
  const minTop = 60;
  const maxTop = canvas.height - GROUND_H - GAP - 60;
  const top = minTop + Math.random() * (maxTop - minTop);
  pipes.push({ x: canvas.width, top, passed: false });
}

function update() {
  if (state === "ready") {
    bird.y = canvas.height / 2 + Math.sin(Date.now() / 200) * 8;
    return;
  }
  if (state !== "playing") return;

  frame++;
  bird.vy += GRAVITY;
  bird.y += bird.vy;

  if (frame % PIPE_INTERVAL === 1) spawnPipe();

  for (const p of pipes) {
    p.x -= PIPE_SPEED;
    if (!p.passed && p.x + PIPE_W < bird.x) {
      p.passed = true;
      score++;
      best = Math.max(best, score);
    }
    // collision
    const inX = bird.x + bird.r > p.x && bird.x - bird.r < p.x + PIPE_W;
    const inGap = bird.y - bird.r > p.top && bird.y + bird.r < p.top + GAP;
    if (inX && !inGap) state = "over";
  }
  pipes = pipes.filter(p => p.x + PIPE_W > 0);

  if (bird.y + bird.r > canvas.height - GROUND_H || bird.y - bird.r < 0) state = "over";
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // pipes
  ctx.fillStyle = "#3cb043";
  ctx.strokeStyle = "#1f6b25";
  ctx.lineWidth = 3;
  for (const p of pipes) {
    ctx.fillRect(p.x, 0, PIPE_W, p.top);
    ctx.strokeRect(p.x, 0, PIPE_W, p.top);
    const bottomY = p.top + GAP;
    const bottomH = canvas.height - GROUND_H - bottomY;
    ctx.fillRect(p.x, bottomY, PIPE_W, bottomH);
    ctx.strokeRect(p.x, bottomY, PIPE_W, bottomH);
  }

  // ground
  ctx.fillStyle = "#ded895";
  ctx.fillRect(0, canvas.height - GROUND_H, canvas.width, GROUND_H);
  ctx.fillStyle = "#73bf2e";
  ctx.fillRect(0, canvas.height - GROUND_H, canvas.width, 12);

  // bird (tilts with velocity)
  ctx.save();
  ctx.translate(bird.x, bird.y);
  ctx.rotate(Math.max(-0.5, Math.min(1.2, bird.vy / 10)));
  ctx.fillStyle = "#f7d51d";
  ctx.beginPath(); ctx.arc(0, 0, bird.r, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = "#000"; ctx.lineWidth = 2; ctx.stroke();
  ctx.fillStyle = "#fff";
  ctx.beginPath(); ctx.arc(5, -4, 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#000";
  ctx.beginPath(); ctx.arc(6, -4, 1.8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#f57c00";
  ctx.beginPath(); ctx.moveTo(10, 0); ctx.lineTo(20, 3); ctx.lineTo(10, 7); ctx.fill();
  ctx.restore();

  // score
  ctx.fillStyle = "#fff";
  ctx.strokeStyle = "#000";
  ctx.lineWidth = 4;
  ctx.font = "bold 40px Arial";
  ctx.textAlign = "center";
  ctx.strokeText(score, canvas.width / 2, 70);
  ctx.fillText(score, canvas.width / 2, 70);

  ctx.font = "bold 20px Arial";
  if (state === "ready") {
    ctx.lineWidth = 3;
    ctx.strokeText("Press SPACE or click to flap", canvas.width / 2, 300);
    ctx.fillText("Press SPACE or click to flap", canvas.width / 2, 300);
  }
  if (state === "over") {
    ctx.font = "bold 36px Arial";
    ctx.strokeText("Game Over", canvas.width / 2, 240);
    ctx.fillText("Game Over", canvas.width / 2, 240);
    ctx.font = "bold 20px Arial";
    ctx.strokeText(`Score: ${score}   Best: ${best}`, canvas.width / 2, 280);
    ctx.fillText(`Score: ${score}   Best: ${best}`, canvas.width / 2, 280);
    ctx.strokeText("Press SPACE or click to restart", canvas.width / 2, 320);
    ctx.fillText("Press SPACE or click to restart", canvas.width / 2, 320);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

reset();
loop();
</script>
</body>
</html>
```

**Controls:** Space, mouse click, or tap to flap. Any of them restarts after a game over.

**Tweaks you might want** (constants at the top):
- `GAP`: smaller is harder
- `GRAVITY` / `FLAP`: change how floaty the bird feels
- `PIPE_SPEED`: faster scrolling

I can add sound, sprites, a day/night cycle, or difficulty that ramps up with score if you'd like.

